# rule: each closed outline shape (2), paint interior non-outline cells with 8
import numpy as np
def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0]); out=[r[:] for r in g]
    for c in set(v for row in g for v in row):
        pass
    # find shapes: connected components of color 2
    vis=[[False]*len(row) for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and not vis[i][j]:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if vis[a][b]: continue
                    vis[a][b]=True; comp.append((a,b))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            y,x=a+dy,b+dx
                            if 0<=y<h and 0<=x<w and g[y][x]==2 and not vis[y][x]: st.append((y,x))
                rowsr=[p for p in comp]
                ys=[p[0] for p in rowsr]; xs=[p[1] for p in rowsr]
                rmin,rmax,cmin,cmax=min(ys),max(ys),min(xs),max(xs)
                # interior = bounding box minus outline cells; also check closed: border of bbox must be all 2
                ok=all(g[y][x]==2 for y in range(rmin,rmax+1) for x in (cmin,cmax)) and all(g[y][x]==2 for x in range(cmin,cmax+1) for y in (rmin,rmax))
                if ok and len(rowsr)>4:
                    for y in range(rmin+1,rmax):
                        for x in range(cmin+1,cmax):
                            if g[y][x]!=2: out[y][x]=8
    return out
